def transform(grid):
    # The 2-pixel marker line extends as a stripe in the color of the isolated marker.
    h, w = len(grid), len(grid[0])
    out = [r[:] for r in grid]
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(r.count(c) for r in grid))
    markers = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    bars = {}
    for color in set(grid[r][c] for r,c in markers):
        pts=[(r,c) for r,c in markers if grid[r][c]==color]
        if len(pts)>=4:
            bars[color]=pts
    # isolated non-background color becomes fill, marker stripes are retained
    stripe_colors=set(bars)
    other=[grid[r][c] for r,c in markers if grid[r][c] not in stripe_colors]
    if not other: return out
    fill=other[0]
    # draw continuous region between horizontal bars: fill from top bar's inner side toward opposite edge,
    # and from bottom bar's inner side toward opposite edge, matching demo vertical stripe case.
    # Bar means same-color segment of at least 2 along an edge; extend marker fill toward it.
    for color,pts in bars.items():
        rows=[r for r,c in pts]; cols=[c for r,c in pts]
        if len(set(rows))==1: # horizontal bar at row
            r=rows[0]; lo=min(cols); hi=max(cols)
            # marker color fills the space between bar and the opposite boundary
            if r==0:
                for rr in range(1,h):
                    for cc in range(lo,hi+1): out[rr][cc]=fill
            elif r==h-1:
                for rr in range(0,h-1):
                    for cc in range(lo,hi+1): out[rr][cc]=fill
        elif len(set(cols))==1:
            c=cols[0]; lo=min(rows); hi=max(rows)
            if c==0:
                for rr in range(lo,hi+1):
                    for cc in range(1,w): out[rr][cc]=fill
            elif c==w-1:
                for rr in range(lo,hi+1):
                    for cc in range(0,w-1): out[rr][cc]=fill
    # Convert the sparse marker pixels into a filled region by extending their diagonal pattern.
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==fill]
    if pts:
        # fill lower-left quadrant/area bounded by marker diagonal, as in demo
        for r,c in pts:
            for rr in range(r+1,h-1):
                for cc in range(1,c+1): out[rr][cc]=fill
    return out
