    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    colors = [x for x in counts if x != bg]
    if len(colors) < 2:
        return out
    bar = max(colors, key=counts.get)
    marker = next(x for x in colors if x != bar)
    # A marker extends along its row/column toward the nearest long bar;
    # replace the marker itself with 4 and fill the intervening cells in marker color.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker:
                continue
            out[r][c] = 4
            # Locate bar segments on the same row and column, then extend toward nearest.
            candidates = []
            for cc in range(w):
                if grid[r][cc] == bar:
                    candidates.append((abs(cc-c), 0, cc))
            for rr in range(h):
                if grid[rr][c] == bar:
                    candidates.append((abs(rr-r), 1, rr))
            if candidates:
                _, axis, target = min(candidates)
                if axis == 0:
                    step = 1 if target > c else -1
                    for cc in range(c+step, target, step):
                        out[r][cc] = marker
                else:
                    step = 1 if target > r else -1
                    for rr in range(r+step, target, step):
                        out[rr][c] = marker
    return out
"
